import { test } from "node:test";
import assert from "node:assert/strict";
import { Database } from "../src/orm/db.ts";
import { Session } from "../src/orm/session.ts";
import { enroll } from "../src/enrollment/courses.ts";
import { register, rosterReport, withdraw } from "../src/enrollment/registrar.ts";

function campus() {
    const db = new Database();
    db.insert("courses", { id: "cs101", title: "Intro to Programming", credits: 4, capacity: 2, seatsTaken: 0, roster: [], waitlist: [] });
    db.insert("courses", { id: "ma201", title: "Linear Algebra", credits: 3, capacity: 30, seatsTaken: 0, roster: [], waitlist: [] });
    for (const id of ["ana", "ben", "cho", "dev"]) db.insert("students", { id, name: id.toUpperCase(), credits: 0, maxCredits: 12 });
    db.log.length = 0;
    return db;
}

const credits = (db: Database, id: string) => new Session(db).get("students", id)?.credits;

test("enrolling puts the student on the course roster", () => {
    const db = campus();
    assert.deepEqual(register(db, "ana", ["cs101"]), { cs101: "enrolled" });
    const report = rosterReport(db, "cs101");
    console.log("cs101 after ana enrolled:", report);
    assert.deepEqual(report, { seatsTaken: 1, roster: ["ana"], waitlist: [] });
});

test("a full course puts the student on the waitlist", () => {
    const db = campus();
    register(db, "ana", ["cs101"]);
    register(db, "ben", ["cs101"]);
    assert.deepEqual(register(db, "cho", ["cs101"]), { cs101: "waitlisted" });
    assert.deepEqual(rosterReport(db, "cs101").waitlist, ["cho"]);
});

test("registering for several courses adds up the student's credits", () => {
    const db = campus();
    assert.deepEqual(register(db, "dev", ["cs101", "ma201"]), { cs101: "enrolled", ma201: "enrolled" });
    // the student row is loaded once and written once, with only the column that changed
    assert.equal(db.log.filter((s) => s.kind === "select" && s.table === "students").length, 1);
    assert.deepEqual(db.log.filter((s) => s.table === "students" && s.kind === "update").map((s) => s.columns), [["credits"]]);
    assert.equal(credits(db, "dev"), 7);
});

test("reading without changing anything sends no writes", () => {
    const db = campus();
    const session = new Session(db);
    session.get("courses", "cs101");
    session.get("students", "ana");
    assert.equal(session.get("courses", "cs101"), session.get("courses", "cs101"));
    assert.equal(session.flush(), 0);
    assert.deepEqual(db.log.map((s) => s.kind), ["select", "select"]);
});

test("dropping a course gives the seat to the first waitlisted student", () => {
    const db = campus();
    for (const id of ["ana", "ben", "cho", "dev"]) register(db, id, ["cs101"]);
    withdraw(db, "ana", "cs101");
    assert.deepEqual(rosterReport(db, "cs101"), { seatsTaken: 2, roster: ["ben", "cho"], waitlist: ["dev"] });
    assert.deepEqual([credits(db, "ana"), credits(db, "cho")], [0, 4]);
});

test("a course created in a session is inserted, and later changes to it are saved", () => {
    const db = campus();
    const session = new Session(db);
    session.add("courses", { id: "ph110", title: "Physics I", credits: 4, capacity: 1, seatsTaken: 0, roster: [], waitlist: [] });
    session.flush();
    assert.equal(enroll(session, "ph110", "ben"), "enrolled");
    session.flush();
    assert.deepEqual(rosterReport(db, "ph110").roster, ["ben"]);
});

test("seat counts match the roster after a busy registration day", () => {
    const db = campus();
    register(db, "ana", ["cs101", "ma201"]);
    register(db, "ben", ["ma201", "cs101"]);
    register(db, "cho", ["cs101"]);
    withdraw(db, "ben", "ma201");
    for (const id of ["cs101", "ma201"]) {
        const { seatsTaken, roster } = rosterReport(db, id);
        assert.equal(roster.length, seatsTaken, `${id}: ${seatsTaken} seats taken but roster is ${JSON.stringify(roster)}`);
    }
});
